package domain

import (
    "errors"
    "strings"
    "time"
)

type ActionClass string
const (
    ActionRead ActionClass = "read"
    ActionDraft ActionClass = "draft"
    ActionExternal ActionClass = "external"
    ActionRestricted ActionClass = "restricted"
)

type TaskStatus string
const (
    StatusOpen TaskStatus = "open"
    StatusApprovalRequired TaskStatus = "approval_required"
    StatusApproved TaskStatus = "approved"
    StatusRejected TaskStatus = "rejected"
    StatusCompleted TaskStatus = "completed"
)

type Task struct {
    ID string `json:"id"`
    Title string `json:"title"`
    Description string `json:"description,omitempty"`
    ActionClass ActionClass `json:"action_class"`
    Status TaskStatus `json:"status"`
    RequestedBy string `json:"requested_by"`
    ApprovedBy string `json:"approved_by,omitempty"`
    DecisionNote string `json:"decision_note,omitempty"`
    CreatedAt time.Time `json:"created_at"`
    UpdatedAt time.Time `json:"updated_at"`
    Version uint64 `json:"version"`
}

var ErrInvalidTask = errors.New("invalid task")

func (t *Task) Validate() error {
    t.Title = strings.TrimSpace(t.Title)
    t.Description = strings.TrimSpace(t.Description)
    if t.Title == "" || len(t.Title) > 200 { return ErrInvalidTask }
    if len(t.Description) > 8000 { return ErrInvalidTask }
    switch t.ActionClass {
    case ActionRead, ActionDraft, ActionExternal, ActionRestricted:
    default:
        return ErrInvalidTask
    }
    if strings.TrimSpace(t.RequestedBy) == "" { return ErrInvalidTask }
    return nil
}
''')

add('services/control-plane/internal/policy/policy.go', r'''
package policy

import (
    "errors"
    "github.com/project-atlas/control-plane/internal/domain"
)

var (
    ErrRestrictedAction = errors.New("restricted action class is not executable")
    ErrApprovalRequired = errors.New("explicit approval is required")
    ErrInvalidTransition = errors.New("invalid task state transition")
)

func InitialStatus(class domain.ActionClass) (domain.TaskStatus, error) {
    switch class {
    case domain.ActionRead, domain.ActionDraft:
        return domain.StatusOpen, nil
    case domain.ActionExternal:
        return domain.StatusApprovalRequired, nil
    case domain.ActionRestricted:
        return "", ErrRestrictedAction
    default:
        return "", ErrInvalidTransition
    }
}

func CanComplete(task domain.Task) error {
    if task.Status == domain.StatusCompleted || task.Status == domain.StatusRejected {
        return ErrInvalidTransition
    }
    if task.ActionClass == domain.ActionRestricted { return ErrRestrictedAction }
    if task.ActionClass == domain.ActionExternal && task.Status != domain.StatusApproved {
        return ErrApprovalRequired
    }
    if task.Status != domain.StatusOpen && task.Status != domain.StatusApproved {
        return ErrInvalidTransition
    }
    return nil
}
''')

add('services/control-plane/internal/ledger/ledger.go', r'''
package ledger

import (
    "bufio"
    "crypto/sha256"
    "encoding/hex"
    "encoding/json"
    "errors"
    "fmt"
    "os"
    "path/filepath"
    "sync"
    "time"
)

type Event struct {
    Sequence uint64 `json:"sequence"`
    Type string `json:"type"`
    TaskID string `json:"task_id"`
    Actor string `json:"actor"`
    Timestamp time.Time `json:"timestamp"`
    Data json.RawMessage `json:"data"`
    PreviousHash string `json:"previous_hash"`
    Hash string `json:"hash"`
}

type Ledger struct {
    mu sync.Mutex
    file *os.File
    events []Event
    head string
}

var ErrCorruptLedger = errors.New("audit ledger integrity verification failed")

func Open(path string) (*Ledger, error) {
    if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil { return nil, err }
    f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o600)
    if err != nil { return nil, err }
    l := &Ledger{file: f}
    scanner := bufio.NewScanner(f)
    scanner.Buffer(make([]byte, 4096), 2*1024*1024)
    var previous string
    var sequence uint64
    for scanner.Scan() {
        var event Event
        if err := json.Unmarshal(scanner.Bytes(), &event); err != nil { f.Close(); return nil, fmt.Errorf("decode ledger: %w", err) }
        if event.Sequence != sequence+1 || event.PreviousHash != previous { f.Close(); return nil, ErrCorruptLedger }
        expected, err := calculateHash(event)
        if err != nil { f.Close(); return nil, err }
        if expected != event.Hash { f.Close(); return nil, ErrCorruptLedger }
        previous = event.Hash
        sequence = event.Sequence
        l.events = append(l.events, event)
    }
    if err := scanner.Err(); err != nil { f.Close(); return nil, err }
    l.head = previous
    return l, nil
}

func calculateHash(event Event) (string, error) {
    event.Hash = ""
    raw, err := json.Marshal(event)
    if err != nil { return "", err }
    sum := sha256.Sum256(raw)
    return hex.EncodeToString(sum[:]), nil
}

func (l *Ledger) Append(event Event) (Event, error) {
    l.mu.Lock()
    defer l.mu.Unlock()
    event.Sequence = uint64(len(l.events)+1)
    event.Timestamp = time.Now().UTC()
    event.PreviousHash = l.head
    hash, err := calculateHash(event)
    if err != nil { return Event{}, err }
    event.Hash = hash
    raw, err := json.Marshal(event)
    if err != nil { return Event{}, err }
    raw = append(raw, '\n')
    n, err := l.file.Write(raw)
    if err != nil { return Event{}, err }
    if n != len(raw) { return Event{}, errors.New("short write to audit ledger") }
    if err := l.file.Sync(); err != nil { return Event{}, err }
    l.events = append(l.events, event)
    l.head = event.Hash
    return event, nil
}

func (l *Ledger) Events() []Event {
    l.mu.Lock(); defer l.mu.Unlock()
    out := make([]Event, len(l.events))
    copy(out, l.events)
    return out
}

func (l *Ledger) Verify() (int, string, error) {
    l.mu.Lock(); defer l.mu.Unlock()
    var previous string
    for i, event := range l.events {
        if event.Sequence != uint64(i+1) || event.PreviousHash != previous { return len(l.events), l.head, ErrCorruptLedger }
        expected, err := calculateHash(event)
        if err != nil { return len(l.events), l.head, err }
        if expected != event.Hash { return len(l.events), l.head, ErrCorruptLedger }
        previous = event.Hash
    }
    return len(l.events), l.head, nil
}

func (l *Ledger) Close() error { return l.file.Close() }
''')

add('services/control-plane/internal/store/store.go', r'''
package store

import (
    "crypto/rand"
    "encoding/hex"
    "encoding/json"
    "errors"
    "sort"
    "sync"
    "time"

    "github.com/project-atlas/control-plane/internal/domain"
    "github.com/project-atlas/control-plane/internal/ledger"
    "github.com/project-atlas/control-plane/internal/policy"
)

var (
    ErrNotFound = errors.New("task not found")
    ErrConflict = errors.New("task state conflict")
)

type Store struct { mu sync.RWMutex; log *ledger.Ledger; tasks map[string]domain.Task }

func New(log *ledger.Ledger) (*Store, error) {
    s := &Store{log: log, tasks: make(map[string]domain.Task)}
    for _, event := range log.Events() {
        if event.Type != "task.snapshot" { continue }
        var task domain.Task
        if err := json.Unmarshal(event.Data, &task); err != nil { return nil, err }
        s.tasks[task.ID] = task
    }
    return s, nil
}

func newID() (string, error) {
    var b [16]byte
    if _, err := rand.Read(b[:]); err != nil { return "", err }
    return hex.EncodeToString(b[:]), nil
}

func (s *Store) persist(task domain.Task, actor, note string) error {
    raw, err := json.Marshal(task)
    if err != nil { return err }
    _, err = s.log.Append(ledger.Event{Type:"task.snapshot", TaskID:task.ID, Actor:actor, Data:raw})
    return err
}

func (s *Store) Create(title, description string, class domain.ActionClass, actor string) (domain.Task, error) {
    s.mu.Lock(); defer s.mu.Unlock()
    status, err := policy.InitialStatus(class); if err != nil { return domain.Task{}, err }
    id, err := newID(); if err != nil { return domain.Task{}, err }
    now := time.Now().UTC()
    task := domain.Task{ID:id, Title:title, Description:description, ActionClass:class, Status:status, RequestedBy:actor, CreatedAt:now, UpdatedAt:now, Version:1}
    if err := task.Validate(); err != nil { return domain.Task{}, err }
    if err := s.persist(task, actor, ""); err != nil { return domain.Task{}, err }
    s.tasks[id] = task
    return task, nil
}

func (s *Store) Get(id string) (domain.Task, bool) { s.mu.RLock(); defer s.mu.RUnlock(); t, ok := s.tasks[id]; return t, ok }

func (s *Store) List() []domain.Task {
    s.mu.RLock(); defer s.mu.RUnlock()
    out := make([]domain.Task, 0, len(s.tasks))
    for _, t := range s.tasks { out = append(out, t) }
    sort.Slice(out, func(i,j int) bool { return out[i].CreatedAt.After(out[j].CreatedAt) })
    return out
}

func (s *Store) Approve(id, actor, decision, reason string) (domain.Task, error) {
    s.mu.Lock(); defer s.mu.Unlock()
    task, ok := s.tasks[id]; if !ok { return domain.Task{}, ErrNotFound }
    if task.ActionClass != domain.ActionExternal || task.Status != domain.StatusApprovalRequired { return domain.Task{}, ErrConflict }
    switch decision {
    case "approve": task.Status = domain.StatusApproved
    case "reject": task.Status = domain.StatusRejected
    default: return domain.Task{}, ErrConflict
    }
    task.ApprovedBy = actor
    task.DecisionNote = reason
    task.UpdatedAt = time.Now().UTC(); task.Version++
    if err := s.persist(task, actor, reason); err != nil { return domain.Task{}, err }
    s.tasks[id] = task
    return task, nil
}

func (s *Store) Complete(id, actor string) (domain.Task, error) {
    s.mu.Lock(); defer s.mu.Unlock()
    task, ok := s.tasks[id]; if !ok { return domain.Task{}, ErrNotFound }
    if err := policy.CanComplete(task); err != nil { return domain.Task{}, err }
    task.Status = domain.StatusCompleted
    task.UpdatedAt = time.Now().UTC(); task.Version++
    if err := s.persist(task, actor, ""); err != nil { return domain.Task{}, err }
    s.tasks[id] = task
    return task, nil
}
''')

add('services/control-plane/internal/httpapi/server.go', r'''
package httpapi

import (
    "crypto/subtle"
    "encoding/json"
    "errors"
    "io"
    "net/http"
    "strings"

    "github.com/project-atlas/control-plane/internal/domain"
    "github.com/project-atlas/control-plane/internal/ledger"
    "github.com/project-atlas/control-plane/internal/policy"
    "github.com/project-atlas/control-plane/internal/store"
)

type Server struct { store *store.Store; ledger *ledger.Ledger; token string }
type errorBody struct { Error string `json:"error"` }
type createRequest struct { Title string `json:"title"`; Description string `json:"description"`; ActionClass domain.ActionClass `json:"action_class"` }
type approvalRequest struct { Decision string `json:"decision"`; Reason string `json:"reason"` }

func New(s *store.Store, l *ledger.Ledger, token string) http.Handler {
    api := &Server{store:s, ledger:l, token:token}
    mux := http.NewServeMux()
    mux.HandleFunc("GET /healthz", api.health)
    mux.Handle("/v1/", api.auth(http.HandlerFunc(api.routeV1)))
    return securityHeaders(mux)
}

func securityHeaders(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("X-Content-Type-Options", "nosniff")
        w.Header().Set("Cache-Control", "no-store")
        w.Header().Set("Referrer-Policy", "no-referrer")
        next.ServeHTTP(w,r)
    })
}

func (s *Server) auth(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        got := strings.TrimPrefix(r.Header.Get("Authorization"), "Bearer ")
        if s.token == "" || len(got) != len(s.token) || subtle.ConstantTimeCompare([]byte(got), []byte(s.token)) != 1 {
            writeError(w, http.StatusUnauthorized, "unauthorized")
            return
        }
        next.ServeHTTP(w,r)
    })
}

func actor(r *http.Request) string {
    a := strings.TrimSpace(r.Header.Get("X-Atlas-Actor"))
    if a == "" { return "local-api-operator" }
    if len(a) > 100 { return "local-api-operator" }
    return a
}

func (s *Server) health(w http.ResponseWriter, r *http.Request) { writeJSON(w,200,map[string]string{"status":"ok"}) }

func (s *Server) routeV1(w http.ResponseWriter, r *http.Request) {
    path := strings.Trim(strings.TrimPrefix(r.URL.Path,"/v1/"),"/")
    if path == "tasks" {
        if r.Method == http.MethodGet { writeJSON(w,200,map[string]any{"tasks":s.store.List()}); return }
        if r.Method == http.MethodPost { s.createTask(w,r); return }
        writeError(w,405,"method not allowed"); return
    }
    if path == "audit/verify" && r.Method == http.MethodGet {
        count, head, err := s.ledger.Verify()
        if err != nil { writeError(w,500,"audit verification failed"); return }
        writeJSON(w,200,map[string]any{"valid":true,"events":count,"head_hash":head}); return
    }
    parts := strings.Split(path,"/")
    if len(parts) == 2 && parts[0] == "tasks" && r.Method == http.MethodGet {
        task, ok := s.store.Get(parts[1]); if !ok { writeError(w,404,"task not found"); return }; writeJSON(w,200,task); return
    }
    if len(parts) == 3 && parts[0] == "tasks" && parts[2] == "approval" && r.Method == http.MethodPost { s.approve(w,r,parts[1]); return }
    if len(parts) == 3 && parts[0] == "tasks" && parts[2] == "complete" && r.Method == http.MethodPost { s.complete(w,r,parts[1]); return }
    writeError(w,404,"route not found")
}

func decode(w http.ResponseWriter, r *http.Request, dst any) error {
    r.Body = http.MaxBytesReader(w,r.Body,1<<20)
    dec := json.NewDecoder(r.Body); dec.DisallowUnknownFields()
    if err := dec.Decode(dst); err != nil { return err }
    if err := dec.Decode(&struct{}{}); err != io.EOF { return errors.New("request must contain one JSON object") }
    return nil
}

func (s *Server) createTask(w http.ResponseWriter,r *http.Request) {
    var req createRequest
    if err := decode(w,r,&req); err != nil { writeError(w,400,"invalid JSON request"); return }
    class := req.ActionClass; if class == "" { class = domain.ActionDraft }
    task, err := s.store.Create(req.Title,req.Description,class,actor(r))
    if err != nil {
        if errors.Is(err,policy.ErrRestrictedAction) { writeError(w,403,"restricted action class is prohibited"); return }
        writeError(w,400,"task validation failed"); return
    }
    writeJSON(w,201,task)
}

func (s *Server) approve(w http.ResponseWriter,r *http.Request,id string) {
    var req approvalRequest
    if err := decode(w,r,&req); err != nil { writeError(w,400,"invalid JSON request"); return }
    if len(req.Reason) > 1000 { writeError(w,400,"reason too long"); return }
    task, err := s.store.Approve(id,actor(r),req.Decision,req.Reason)
    if err != nil { writeError(w,409,err.Error()); return }
    writeJSON(w,200,task)
}

func (s *Server) complete(w http.ResponseWriter,r *http.Request,id string) {
    task, err := s.store.Complete(id,actor(r))
    if err != nil {
        status := 409
        if errors.Is(err,store.ErrNotFound) { status = 404 }
        if errors.Is(err,policy.ErrApprovalRequired) { status = 403 }
        if errors.Is(err,policy.ErrRestrictedAction) { status = 403 }
        writeError(w,status,err.Error()); return
    }
    writeJSON(w,200,task)
}

func writeJSON(w http.ResponseWriter,status int,v any) { w.Header().Set("Content-Type","application/json; charset=utf-8"); w.WriteHeader(status); _ = json.NewEncoder(w).Encode(v) }
func writeError(w http.ResponseWriter,status int,msg string) { writeJSON(w,status,errorBody{Error:msg}) }
''')

add('services/control-plane/cmd/atlasd/main.go', r'''
package main

import (
    "log/slog"
    "net/http"
    "os"
    "path/filepath"
    "time"

    "github.com/project-atlas/control-plane/internal/httpapi"
    "github.com/project-atlas/control-plane/internal/ledger"
    "github.com/project-atlas/control-plane/internal/store"
)

func main() {
    logger := slog.New(slog.NewJSONHandler(os.Stdout,nil))
    token := os.Getenv("ATLAS_API_TOKEN")
    if len(token) < 16 { logger.Error("ATLAS_API_TOKEN must be set to at least 16 characters"); os.Exit(1) }
    dataDir := os.Getenv("ATLAS_DATA_DIR"); if dataDir == "" { dataDir = ".atlas-data" }
    log, err := ledger.Open(filepath.Join(dataDir,"audit.jsonl")); if err != nil { logger.Error("open audit ledger", "error",err); os.Exit(1) }
    defer log.Close()
    st, err := store.New(log); if err != nil { logger.Error("replay task store", "error",err); os.Exit(1) }
    addr := os.Getenv("ATLAS_ADDR"); if addr == "" { addr = "127.0.0.1:8080" }
    srv := &http.Server{Addr:addr, Handler:httpapi.New(st,log,token), ReadHeaderTimeout:5*time.Second, ReadTimeout:10*time.Second, WriteTimeout:15*time.Second, IdleTimeout:60*time.Second, MaxHeaderBytes:1<<20}
    logger.Info("ATLAS control plane starting", "addr",addr,"data_dir",dataDir)
    if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed { logger.Error("server failure", "error",err); os.Exit(1) }
}
''')

add('services/control-plane/internal/ledger/ledger_test.go', r'''
package ledger

import (
    "encoding/json"
    "os"
    "path/filepath"
    "testing"
)

func TestHashChainDetectsMutation(t *testing.T) {
    path := filepath.Join(t.TempDir(),"audit.jsonl")
    l,err := Open(path); if err != nil { t.Fatal(err) }
    data,_ := json.Marshal(map[string]string{"value":"one"})
    if _,err := l.Append(Event{Type:"test",TaskID:"x",Actor:"tester",Data:data}); err != nil { t.Fatal(err) }
    if _,_,err := l.Verify(); err != nil { t.Fatal(err) }
    if err := l.Close(); err != nil { t.Fatal(err) }
    raw,err := os.ReadFile(path); if err != nil { t.Fatal(err) }
    for i := range raw { if raw[i] == 'o' { raw[i] = 'X'; break } }
    if err := os.WriteFile(path,raw,0o600); err != nil { t.Fatal(err) }
    if _,err := Open(path); err == nil { t.Fatal("expected tamper detection") }
}
''')

add('services/control-plane/internal/store/store_test.go', r'''
package store

import (
    "path/filepath"
    "testing"
    "github.com/project-atlas/control-plane/internal/domain"
    "github.com/project-atlas/control-plane/internal/ledger"
    "github.com/project-atlas/control-plane/internal/policy"
)

func newTestStore(t *testing.T) (*Store,*ledger.Ledger) {
    t.Helper(); l,err := ledger.Open(filepath.Join(t.TempDir(),"audit.jsonl")); if err != nil { t.Fatal(err) }
    s,err := New(l); if err != nil { t.Fatal(err) }; return s,l
}

func TestExternalActionRequiresApproval(t *testing.T) {
    s,l := newTestStore(t); defer l.Close()
    task,err := s.Create("Send outreach","draft message",domain.ActionExternal,"tester"); if err != nil { t.Fatal(err) }
    if task.Status != domain.StatusApprovalRequired { t.Fatalf("status=%s",task.Status) }
    if _,err := s.Complete(task.ID,"tester"); err != policy.ErrApprovalRequired { t.Fatalf("expected approval requirement, got %v",err) }
    task,err = s.Approve(task.ID,"tester","approve","reviewed"); if err != nil { t.Fatal(err) }
    if task.Status != domain.StatusApproved { t.Fatalf("status=%s",task.Status) }
    task,err = s.Complete(task.ID,"tester"); if err != nil { t.Fatal(err) }
    if task.Status != domain.StatusCompleted { t.Fatalf("status=%s",task.Status) }
}

