add('services/intelligence/atlas_intelligence.py', r'''
"""ATLAS deterministic intelligence baseline.

This module deliberately does not call a hosted model. It provides a reproducible
baseline and a provider boundary for later model-backed implementations.
"""
from __future__ import annotations
from dataclasses import dataclass
from typing import Protocol
import re

SKILL_CATALOG = (
    "python", "sql", "excel", "power bi", "tableau", "communication",
    "stakeholder management", "project management", "data analysis",
    "process improvement", "reporting", "procurement", "operations",
    "financial analysis", "machine learning", "typescript", "java",
    "cloud", "aws", "azure", "customer service", "research", "automation",
)

@dataclass(frozen=True)
class JobAnalysisRequest:
    job_title: str
    job_description: str
    profile_evidence: tuple[str, ...]

@dataclass(frozen=True)
class SkillEvidence:
    skill: str
    matched: bool
    evidence: tuple[str, ...]

@dataclass(frozen=True)
class JobAnalysis:
    engine: str
    job_title: str
    extracted_requirements: tuple[str, ...]
    evidence_map: tuple[SkillEvidence, ...]
    unsupported_requirements: tuple[str, ...]
    disclaimer: str

class IntelligenceProvider(Protocol):
    def analyze_job(self, request: JobAnalysisRequest) -> JobAnalysis: ...

class DeterministicProvider:
    """Transparent keyword baseline; not semantic matching or an LLM."""
    def __init__(self, catalog: tuple[str, ...] = SKILL_CATALOG) -> None:
        self.catalog = tuple(sorted(set(catalog), key=len, reverse=True))

    @staticmethod
    def _normalise(text: str) -> str:
        return re.sub(r"\s+", " ", text.casefold()).strip()

    def analyze_job(self, request: JobAnalysisRequest) -> JobAnalysis:
        description = self._normalise(request.job_description)
        evidence = tuple(self._normalise(item) for item in request.profile_evidence if item.strip())
        requirements = tuple(skill for skill in self.catalog if skill in description)
        results: list[SkillEvidence] = []
        missing: list[str] = []
        for skill in requirements:
            proof = tuple(
                request.profile_evidence[i]
                for i, item in enumerate(evidence)
                if skill in item
            )
            results.append(SkillEvidence(skill=skill, matched=bool(proof), evidence=proof))
            if not proof:
                missing.append(skill)
        return JobAnalysis(
            engine="deterministic-keyword-baseline",
            job_title=request.job_title.strip(),
            extracted_requirements=requirements,
            evidence_map=tuple(results),
            unsupported_requirements=tuple(missing),
            disclaimer=("Keyword baseline only. It does not establish qualification, suitability or hiring probability. "
                        "Review the original job description and evidence manually."),
        )
''')

add('services/intelligence/app.py', r'''
from __future__ import annotations
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from atlas_intelligence import DeterministicProvider, JobAnalysisRequest

PROVIDER = DeterministicProvider()
MAX_BODY = 128 * 1024

class Handler(BaseHTTPRequestHandler):
    server_version = "ATLAS-Intelligence/0.1"

    def _send(self, status: int, data: dict) -> None:
        raw = json.dumps(data, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(raw)

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self._send(200, {"status": "ok", "engine": "deterministic-keyword-baseline"})
        else:
            self._send(404, {"error": "not found"})

    def do_POST(self) -> None:
        if self.path != "/v1/job-analysis":
            self._send(404, {"error": "not found"})
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            self._send(400, {"error": "invalid content length"})
            return
        if length <= 0 or length > MAX_BODY:
            self._send(413, {"error": "body missing or too large"})
            return
        try:
            payload = json.loads(self.rfile.read(length))
            if not isinstance(payload, dict):
                raise ValueError("body must be an object")
            title = payload.get("job_title", "")
            description = payload.get("job_description", "")
            proof = payload.get("profile_evidence", [])
            if not isinstance(title, str) or not isinstance(description, str) or not isinstance(proof, list):
                raise ValueError("invalid field types")
            if len(title) > 200 or len(description) > 25_000 or len(proof) > 100:
                raise ValueError("field limit exceeded")
            if any(not isinstance(x, str) or len(x) > 2_000 for x in proof):
                raise ValueError("profile_evidence must contain short strings")
            request = JobAnalysisRequest(title, description, tuple(proof))
            result = PROVIDER.analyze_job(request)
            self._send(200, {
                "engine": result.engine,
                "job_title": result.job_title,
                "extracted_requirements": list(result.extracted_requirements),
                "evidence_map": [
                    {"skill": x.skill, "matched": x.matched, "evidence": list(x.evidence)}
                    for x in result.evidence_map
                ],
                "unsupported_requirements": list(result.unsupported_requirements),
                "disclaimer": result.disclaimer,
            })
        except (json.JSONDecodeError, ValueError) as exc:
            self._send(400, {"error": str(exc)})
        except Exception:
            self._send(500, {"error": "internal analysis error"})

    def log_message(self, fmt: str, *args) -> None:
        print("ATLAS intelligence:", fmt % args)

if __name__ == "__main__":
    host = os.getenv("ATLAS_INTELLIGENCE_HOST", "127.0.0.1")
    port = int(os.getenv("ATLAS_INTELLIGENCE_PORT", "8090"))
    server = ThreadingHTTPServer((host, port), Handler)
    print(f"ATLAS intelligence listening on http://{host}:{port}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()
''')

