#![forbid(unsafe_code)]
//! Pure, deterministic authorization decisions for ATLAS capabilities.
//! This crate is a reference module and is not yet wired into the Go control plane.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ActionClass { Read, Draft, External, Restricted }

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Decision { Allow, RequireApproval, Deny }

#[derive(Debug)]
pub struct Subject<'a> {
    pub authenticated: bool,
    pub workspace_id: &'a str,
    pub scopes: &'a [&'a str],
}

#[derive(Debug)]
pub struct Request<'a> {
    pub workspace_id: &'a str,
    pub action_class: ActionClass,
    pub approval_granted: bool,
}

fn has_scope(subject: &Subject<'_>, scope: &str) -> bool {
    subject.scopes.iter().any(|candidate| *candidate == scope)
}

pub fn authorize(subject: &Subject<'_>, request: &Request<'_>) -> Decision {
    if !subject.authenticated || subject.workspace_id != request.workspace_id {
        return Decision::Deny;
    }

    match request.action_class {
        ActionClass::Read => {
            if has_scope(subject, "atlas:read") || has_scope(subject, "atlas:write") {
                Decision::Allow
            } else { Decision::Deny }
        }
        ActionClass::Draft => {
            if has_scope(subject, "atlas:write") { Decision::Allow } else { Decision::Deny }
        }
        ActionClass::External => {
            if !has_scope(subject, "atlas:external") { return Decision::Deny; }
            if request.approval_granted { Decision::Allow } else { Decision::RequireApproval }
        }
        ActionClass::Restricted => Decision::Deny,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn denies_cross_workspace_access() {
        let subject = Subject { authenticated: true, workspace_id: "w1", scopes: &["atlas:read"] };
        let req = Request { workspace_id: "w2", action_class: ActionClass::Read, approval_granted: false };
        assert_eq!(authorize(&subject, &req), Decision::Deny);
    }

    #[test]
    fn external_action_requires_explicit_approval() {
        let subject = Subject { authenticated: true, workspace_id: "w1", scopes: &["atlas:external"] };
        let req = Request { workspace_id: "w1", action_class: ActionClass::External, approval_granted: false };
        assert_eq!(authorize(&subject, &req), Decision::RequireApproval);
    }

    #[test]
    fn restricted_actions_are_denied() {
        let subject = Subject { authenticated: true, workspace_id: "w1", scopes: &["atlas:external"] };
        let req = Request { workspace_id: "w1", action_class: ActionClass::Restricted, approval_granted: true };
        assert_eq!(authorize(&subject, &req), Decision::Deny);
    }
}
''')

