    JobDescription string `json:"job_description"`
    ProfileEvidence []string `json:"profile_evidence"`
}

func (s *Server) jobAnalysis(w http.ResponseWriter, r *http.Request) {
    var input jobAnalysisRequest
    if err := decode(w, r, &input); err != nil { writeError(w, 400, "invalid JSON request"); return }
    if len(input.JobTitle) > 200 || len(input.JobDescription) > 25000 || len(input.ProfileEvidence) > 100 {
