    }
    for _, evidence := range input.ProfileEvidence {
        if len(evidence) > 2000 { writeError(w, 400, "profile evidence item too long"); return }
    }
    raw, err := json.Marshal(input)
    if err != nil { writeError(w, 400, "invalid request"); return }
    ctx, cancel := context.WithTimeout(r.Context(), 8*time.Second)
    defer cancel()
    req, err := http.NewRequestWithContext(ctx, http.MethodPost, s.intelligenceURL+"/v1/job-analysis", bytes.NewReader(raw))
    if err != nil { writeError(w, 500, "could not construct intelligence request"); return }
    req.Header.Set("Content-Type", "application/json")
    resp, err := s.client.Do(req)
    if err != nil { writeError(w, 502, "intelligence service unavailable"); return }
    defer resp.Body.Close()
    body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
    if err != nil { writeError(w, 502, "intelligence response could not be read"); return }
    if resp.StatusCode < 200 || resp.StatusCode >= 300 {
        writeError(w, 502, fmt.Sprintf("intelligence service returned HTTP %d", resp.StatusCode)); return
    }
    w.Header().Set("Content-Type", "application/json; charset=utf-8")
    w.Header().Set("Cache-Control", "no-store")
    w.WriteHeader(200)
    _, _ = w.Write(body)
}

